import { useState, useEffect, useRef } from 'react';
import { getPasswordStrength } from '../utils/helpers';

const API = 'http://localhost:5000/api';

const AuthPage = ({ store, onLogin }) => {
  const [tab,        setTab]        = useState('login'); // login | register | forgot
  const [step,       setStep]       = useState(1);       // forgot: 1=email, 2=otp, 3=newpwd
  const [form,       setForm]       = useState({ name:'', email:'', password:'', department:'', year:'1st Year', new_password:'', confirm:'' });
  const [otpDigits,  setOtpDigits]  = useState(['','','','','','']);
  const [error,      setError]      = useState('');
  const [success,    setSuccess]    = useState('');
  const [loading,    setLoading]    = useState(false);
  const [devOtp,     setDevOtp]     = useState('');
  const [emailCfg,   setEmailCfg]   = useState(null);
  const [otpTimer,   setOtpTimer]   = useState(0);
  const timerRef = useRef();

  const handle    = (e) => setForm(f => ({ ...f, [e.target.name]: e.target.value }));
  const pwdStr    = getPasswordStrength(form.password);
  const newStr    = getPasswordStrength(form.new_password);
  const otpValue  = otpDigits.join('');

  useEffect(() => {
    fetch(`${API}/auth/email-status`).then(r => r.json()).then(d => setEmailCfg(d.configured)).catch(() => setEmailCfg(false));
    return () => clearInterval(timerRef.current);
  }, []);

  const resetForgot = () => { setStep(1); setOtpDigits(['','','','','','']); setDevOtp(''); setOtpTimer(0); clearInterval(timerRef.current); };
  const switchTab   = (t) => { setTab(t); setError(''); setSuccess(''); resetForgot(); };

  const startTimer = () => {
    setOtpTimer(600);
    clearInterval(timerRef.current);
    timerRef.current = setInterval(() => setOtpTimer(t => { if (t <= 1) { clearInterval(timerRef.current); return 0; } return t - 1; }), 1000);
  };

  const fmtTime = (s) => `${Math.floor(s/60)}:${String(s%60).padStart(2,'0')}`;

  const post = async (path, body) => {
    const res = await fetch(`${API}${path}`, { method:'POST', headers:{'Content-Type':'application/json'}, body: JSON.stringify(body) });
    return res.json();
  };

  // OTP box handlers
  const handleOtpInput = (i, val) => {
    const digit = val.replace(/\D/g,'').slice(-1); // only last digit
    const arr = [...otpDigits];
    arr[i] = digit;
    setOtpDigits(arr);
    if (digit && i < 5) setTimeout(() => document.getElementById(`otp-${i+1}`)?.focus(), 0);
  };

  const handleOtpKey = (i, e) => {
    if (e.key === 'Backspace') {
      e.preventDefault();
      const arr = [...otpDigits];
      if (arr[i]) { arr[i] = ''; setOtpDigits(arr); }
      else if (i > 0) { arr[i-1] = ''; setOtpDigits(arr); setTimeout(() => document.getElementById(`otp-${i-1}`)?.focus(), 0); }
    } else if (e.key === 'ArrowLeft' && i > 0) { document.getElementById(`otp-${i-1}`)?.focus(); }
    else if (e.key === 'ArrowRight' && i < 5) { document.getElementById(`otp-${i+1}`)?.focus(); }
  };

  const handleOtpPaste = (e) => {
    e.preventDefault();
    const digits = e.clipboardData.getData('text').replace(/\D/g,'').slice(0,6).split('');
    const arr = ['','','','','',''];
    digits.forEach((d,i) => { arr[i] = d; });
    setOtpDigits(arr);
    const next = Math.min(digits.length, 5);
    setTimeout(() => document.getElementById(`otp-${next}`)?.focus(), 0);
  };

  // ── LOGIN ────────────────────────────────────
  const handleLogin = async () => {
    setLoading(true); setError('');
    const ok = await store.login(form.email, form.password);
    if (!ok) setError('Invalid email or password.');
    else if (onLogin) onLogin();
    setLoading(false);
  };

  // ── REGISTER ─────────────────────────────────
  const handleRegister = async () => {
    setError('');
    if (!form.name || !form.email || !form.password) return setError('All fields are required.');
    if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(form.email)) return setError('Enter a valid email.');
    if (!pwdStr.strong) return setError('Password must meet all 4 requirements.');
    setLoading(true);
    try {
      const data = await post('/auth/register', { name:form.name, email:form.email, password:form.password, department:form.department, year:form.year });
      if (data.error) setError(data.error);
      else { setSuccess('✅ Account created! Please login.'); switchTab('login'); }
    } catch { setError('Cannot connect to server.'); }
    setLoading(false);
  };

  // ── STEP 1: SEND OTP ─────────────────────────
  const handleSendOtp = async () => {
    setError(''); setSuccess(''); setDevOtp('');
    if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(form.email)) return setError('Enter a valid email address.');
    setLoading(true);
    try {
      const data = await post('/auth/send-otp', { email: form.email });
      if (data.error) { setError(data.error); }
      else {
        startTimer();
        setEmailCfg(data.email_configured);
        if (data.dev_otp) { setDevOtp(data.dev_otp); setSuccess('Dev mode: OTP shown below (email not configured).'); }
        else setSuccess(`✅ OTP sent to ${form.email}! Check your inbox.`);
        setStep(2);
      }
    } catch { setError('Cannot connect to server.'); }
    setLoading(false);
  };

  // ── STEP 2: VERIFY OTP ───────────────────────
  const handleVerifyOtp = async () => {
    setError(''); setSuccess('');
    if (otpValue.length !== 6) return setError('Please enter all 6 digits of the OTP.');
    setLoading(true);
    try {
      const res  = await fetch(`${API}/auth/verify-otp`, {
        method:'POST', headers:{'Content-Type':'application/json'},
        body: JSON.stringify({ email: form.email, otp: otpValue })
      });
      const data = await res.json();
      if (data.error) { setError(data.error); }
      else { setStep(3); setSuccess('✅ OTP verified! Set your new password below.'); clearInterval(timerRef.current); }
    } catch { setError('Cannot connect to server.'); }
    setLoading(false);
  };

  // ── STEP 3: SET NEW PASSWORD ─────────────────
  const handleResetPassword = async () => {
    setError('');
    if (!form.new_password) return setError('Enter a new password.');
    if (!newStr.strong) return setError('Password must meet all 4 requirements.');
    if (form.new_password !== form.confirm) return setError('Passwords do not match.');
    setLoading(true);
    try {
      const data = await post('/auth/reset-password', { email: form.email, otp: otpValue, new_password: form.new_password });
      if (data.error) setError(data.error);
      else { setSuccess('✅ Password reset! Redirecting to login...'); setTimeout(() => switchTab('login'), 2000); }
    } catch { setError('Cannot connect to server.'); }
    setLoading(false);
  };

  const PwdMeter = ({ str }) => !str ? null : (
    <div style={{ marginTop:10, padding:'10px 14px', background:'#f5f6ff', borderRadius:8, border:'1px solid #dde0f5' }}>
      <div style={{ display:'grid', gridTemplateColumns:'1fr 1fr', gap:4, marginBottom:8 }}>
        {[{k:'length',l:'8+ characters'},{k:'uppercase',l:'Uppercase'},{k:'number',l:'Number'},{k:'special',l:'Special char'}].map(({k,l}) => (
          <div key={k} style={{ display:'flex', gap:5, alignItems:'center', fontSize:11 }}>
            <span style={{ color: str.checks[k]?'#059669':'#dc2626' }}>{str.checks[k]?'✓':'✕'}</span>
            <span style={{ color: str.checks[k]?'#059669':'#9ca3af' }}>{l}</span>
          </div>
        ))}
      </div>
      <div style={{ height:4, background:'#dde0f5', borderRadius:3, overflow:'hidden' }}>
        <div style={{ height:'100%', borderRadius:3, transition:'width 0.3s', width:`${str.passed*25}%`, background: str.passed<=1?'#dc2626':str.passed===2?'#d97706':str.passed===3?'#0ea5e9':'#059669' }} />
      </div>
    </div>
  );

  // Step indicator for forgot flow
  const StepIndicator = () => (
    <div style={{ display:'flex', alignItems:'center', justifyContent:'center', gap:0, marginBottom:20 }}>
      {[{n:1,l:'Email'},{n:2,l:'OTP'},{n:3,l:'Password'}].map(({n,l}, idx) => (
        <div key={n} style={{ display:'flex', alignItems:'center' }}>
          <div style={{ display:'flex', flexDirection:'column', alignItems:'center', gap:4 }}>
            <div style={{ width:28, height:28, borderRadius:'50%', display:'flex', alignItems:'center', justifyContent:'center', fontSize:12, fontWeight:700,
              background: step > n ? 'var(--success)' : step === n ? 'var(--accent)' : 'var(--surface2)',
              color: step >= n ? 'white' : 'var(--text3)',
              border: `2px solid ${step > n ? 'var(--success)' : step === n ? 'var(--accent)' : 'var(--border)'}`,
              transition:'all 0.3s'
            }}>
              {step > n ? '✓' : n}
            </div>
            <div style={{ fontSize:10, color: step === n ? 'var(--accent)' : 'var(--text3)', fontWeight: step === n ? 700 : 400 }}>{l}</div>
          </div>
          {idx < 2 && <div style={{ width:40, height:2, background: step > n ? 'var(--success)' : 'var(--border)', margin:'0 4px', marginBottom:18, transition:'background 0.3s' }} />}
        </div>
      ))}
    </div>
  );

  const OtpBoxes = () => (
    <div style={{ display:'flex', gap:8, justifyContent:'center', margin:'8px 0' }}>
      {[0,1,2,3,4,5].map(i => (
        <input
          key={i}
          id={`otp-${i}`}
          type="text"
          inputMode="numeric"
          autoComplete="one-time-code"
          maxLength={2}
          value={otpDigits[i]}
          onChange={e => handleOtpInput(i, e.target.value)}
          onKeyDown={e => handleOtpKey(i, e)}
          onPaste={handleOtpPaste}
          onFocus={e => e.target.select()}
          disabled={step !== 2}
          style={{
            width:48, height:56, textAlign:'center', fontSize:24, fontWeight:800,
            fontFamily:'Syne', borderRadius:10,
            border: `2px solid ${otpDigits[i] ? 'var(--accent)' : 'var(--border2)'}`,
            background: otpDigits[i] ? 'rgba(99,102,241,0.06)' : 'var(--surface2)',
            color:'var(--text)', outline:'none',
            transition:'border-color 0.15s, background 0.15s',
            cursor: step !== 2 ? 'not-allowed' : 'text',
          }}
        />
      ))}
    </div>
  );

  return (
    <div className="auth-page">
      <div className="auth-card">
        <div className="auth-logo">
          <div className="auth-logo-title">Exam<span>AI</span></div>
          <div className="auth-logo-sub">GenAI Examination Platform</div>
        </div>

        {/* Tabs */}
        {(tab==='login'||tab==='register') && (
          <div className="auth-tabs">
            <div className={`auth-tab ${tab==='login'?'active':''}`} onClick={() => switchTab('login')}>Login</div>
            <div className={`auth-tab ${tab==='register'?'active':''}`} onClick={() => switchTab('register')}>Register</div>
          </div>
        )}

        {/* Forgot header */}
        {tab==='forgot' && (
          <div style={{ marginBottom:16 }}>
            <button className="btn btn-ghost btn-sm" onClick={() => switchTab('login')} style={{ marginBottom:10 }}>← Back to Login</button>
            <div style={{ fontFamily:'Syne', fontWeight:800, fontSize:18, color:'var(--text)', marginBottom:4 }}>🔑 Forgot Password</div>
            <StepIndicator />
          </div>
        )}

        {/* Alerts */}
        {error   && <div className="alert alert-error" style={{ marginBottom:12 }}>{error}</div>}
        {success && <div style={{ background:'rgba(5,150,105,0.08)', border:'1px solid rgba(5,150,105,0.3)', color:'var(--success)', borderRadius:8, padding:'10px 14px', marginBottom:12, fontSize:13 }}>{success}</div>}

        {/* ── LOGIN ── */}
        {tab==='login' && (<>
          <div className="form-group">
            <label className="form-label">Email</label>
            <input className="form-input" name="email" type="email" value={form.email} onChange={handle} placeholder="your@email.com" onKeyDown={e => e.key==='Enter'&&handleLogin()} autoFocus />
          </div>
          <div className="form-group">
            <label className="form-label">Password</label>
            <input className="form-input" name="password" type="password" value={form.password} onChange={handle} placeholder="••••••••" onKeyDown={e => e.key==='Enter'&&handleLogin()} />
          </div>
          <div style={{ textAlign:'right', marginTop:-8, marginBottom:14 }}>
            <span style={{ fontSize:12, color:'var(--accent)', cursor:'pointer', fontWeight:600 }} onClick={() => switchTab('forgot')}>Forgot password?</span>
          </div>
          <button className="btn btn-primary btn-lg" style={{ width:'100%' }} onClick={handleLogin} disabled={loading}>
            {loading ? <><div className="spinner"/>Authenticating...</> : '→ Login'}
          </button>
          <div className="auth-footer">
            <div style={{ fontWeight:600, marginBottom:4 }}>Default admin:</div>
            <div>Email: <strong>admin@dexam.com</strong> &nbsp;·&nbsp; Password: <strong>Admin@123</strong></div>
            <div style={{ marginTop:6, fontSize:11, color:'var(--text3)' }}>ℹ️ Admin accounts are created by the system administrator only</div>
          </div>
        </>)}

        {/* ── REGISTER ── */}
        {tab==='register' && (<>
          <div style={{ marginBottom:14, padding:'10px 14px', background:'rgba(99,102,241,0.06)', borderRadius:8, border:'1px solid rgba(99,102,241,0.2)', display:'flex', gap:10, alignItems:'center' }}>
            <span style={{ fontSize:20 }}>👨‍🎓</span>
            <div><div style={{ fontSize:13, fontWeight:600, color:'var(--accent)' }}>Student Registration</div><div style={{ fontSize:11, color:'var(--text3)' }}>Only students can register here.</div></div>
          </div>
          <div className="form-group"><label className="form-label">Full Name</label><input className="form-input" name="name" value={form.name} onChange={handle} placeholder="Your full name" /></div>
          <div className="form-group"><label className="form-label">Email</label><input className="form-input" name="email" type="email" value={form.email} onChange={handle} placeholder="you@example.com" /></div>
          <div className="form-row form-row-2">
            <div className="form-group"><label className="form-label">Department</label><input className="form-input" name="department" value={form.department} onChange={handle} placeholder="e.g. CS" /></div>
            <div className="form-group"><label className="form-label">Year</label>
              <select className="form-select" name="year" value={form.year} onChange={handle}>
                {['1st Year','2nd Year','3rd Year','4th Year'].map(y => <option key={y}>{y}</option>)}
              </select>
            </div>
          </div>
          <div className="form-group">
            <label className="form-label">Password</label>
            <input className="form-input" name="password" type="password" value={form.password} onChange={handle} placeholder="Min 8 chars, uppercase, number, symbol" />
            {form.password.length > 0 && <PwdMeter str={pwdStr} />}
          </div>
          <button className="btn btn-primary btn-lg" style={{ width:'100%' }} onClick={handleRegister} disabled={loading}>
            {loading ? <><div className="spinner"/>Creating account...</> : '→ Register as Student'}
          </button>
          <div style={{ textAlign:'center', fontSize:12, color:'var(--text3)', marginTop:12 }}>
            Already have an account? <span style={{ color:'var(--accent)', cursor:'pointer', fontWeight:600 }} onClick={() => switchTab('login')}>Login here</span>
          </div>
        </>)}

        {/* ── FORGOT PASSWORD ── */}
        {tab==='forgot' && (<>

          {/* STEP 1 — Enter email */}
          {step===1 && (<>
            <div className="form-group">
              <label className="form-label">Your Registered Email</label>
              <input className="form-input" name="email" type="email" value={form.email} onChange={handle}
                placeholder="you@email.com" onKeyDown={e => e.key==='Enter'&&handleSendOtp()} autoFocus />
              <div style={{ fontSize:11, color:'var(--text3)', marginTop:4 }}>
                {emailCfg ? '📧 A 6-digit OTP will be sent to your email' : '⚠ Email not configured — OTP will appear on screen'}
              </div>
            </div>
            <button className="btn btn-primary btn-lg" style={{ width:'100%' }} onClick={handleSendOtp} disabled={loading}>
              {loading ? <><div className="spinner"/>Sending OTP...</> : '→ Send OTP'}
            </button>
          </>)}

          {/* STEP 2 — Enter OTP */}
          {step===2 && (<>
            <div style={{ textAlign:'center', marginBottom:6 }}>
              <div style={{ fontSize:13, color:'var(--text2)' }}>OTP sent to <strong style={{ color:'var(--text)' }}>{form.email}</strong></div>
              {otpTimer > 0
                ? <div style={{ fontSize:12, color:'var(--success)', marginTop:4 }}>⏰ Expires in {fmtTime(otpTimer)}</div>
                : <div style={{ fontSize:12, color:'var(--danger)', marginTop:4 }}>⚠ OTP expired — please request a new one</div>
              }
            </div>

            {/* Dev mode OTP display */}
            {devOtp && (
              <div style={{ marginBottom:16, padding:14, background:'rgba(245,158,11,0.08)', border:'2px dashed rgba(245,158,11,0.4)', borderRadius:10, textAlign:'center' }}>
                <div style={{ fontSize:11, fontWeight:700, color:'#d97706', marginBottom:8, textTransform:'uppercase', letterSpacing:1 }}>⚠ Dev Mode OTP</div>
                <div style={{ fontFamily:'monospace', fontSize:32, fontWeight:900, letterSpacing:10, color:'var(--text)', marginBottom:8 }}>{devOtp}</div>
                <button className="btn btn-secondary btn-sm" onClick={() => {
                  navigator.clipboard.writeText(devOtp);
                  // Auto-fill boxes
                  const arr = devOtp.split('');
                  setOtpDigits(arr);
                  store.addToast('OTP copied & filled!','success');
                }}>📋 Copy & Auto-fill</button>
              </div>
            )}

            <div className="form-group">
              <label className="form-label" style={{ textAlign:'center', display:'block' }}>Enter 6-Digit OTP</label>
              <OtpBoxes />
            </div>

            <button className="btn btn-primary btn-lg" style={{ width:'100%', marginTop:4 }}
              onClick={handleVerifyOtp}
              disabled={loading || otpValue.length !== 6 || otpTimer === 0}>
              {loading ? <><div className="spinner"/>Verifying...</> : '→ Verify OTP'}
            </button>

            <div style={{ textAlign:'center', marginTop:10 }}>
              <span style={{ fontSize:12, color:'var(--text3)' }}>Didn't receive it? </span>
              <span style={{ fontSize:12, color:'var(--accent)', cursor: otpTimer > 540 ? 'not-allowed':'pointer', fontWeight:600, opacity: otpTimer > 540 ? 0.5:1 }}
                onClick={() => { if (otpTimer <= 540) { resetForgot(); setStep(1); } }}>
                Resend OTP {otpTimer > 540 ? `(wait ${fmtTime(otpTimer - 540)})` : ''}
              </span>
            </div>
          </>)}

          {/* STEP 3 — Set new password */}
          {step===3 && (<>
            <div style={{ padding:'10px 14px', background:'rgba(5,150,105,0.06)', borderRadius:8, border:'1px solid rgba(5,150,105,0.2)', marginBottom:16, display:'flex', gap:8, alignItems:'center' }}>
              <span style={{ fontSize:18 }}>✅</span>
              <div style={{ fontSize:13, color:'var(--success)', fontWeight:600 }}>Identity verified! Set your new password.</div>
            </div>
            <div className="form-group">
              <label className="form-label">New Password</label>
              <input className="form-input" name="new_password" type="password" value={form.new_password} onChange={handle}
                placeholder="Min 8 chars, uppercase, number, symbol" autoFocus />
              {form.new_password.length > 0 && <PwdMeter str={newStr} />}
            </div>
            <div className="form-group">
              <label className="form-label">Confirm New Password</label>
              <input className="form-input" name="confirm" type="password" value={form.confirm} onChange={handle}
                placeholder="Re-enter new password"
                onKeyDown={e => e.key==='Enter'&&handleResetPassword()}
                style={{ borderColor: form.confirm && form.confirm !== form.new_password ? 'var(--danger)' : form.confirm && form.confirm === form.new_password ? 'var(--success)' : undefined }} />
              {form.confirm && form.confirm !== form.new_password && <div style={{ fontSize:11, color:'var(--danger)', marginTop:4 }}>Passwords do not match</div>}
              {form.confirm && form.confirm === form.new_password && <div style={{ fontSize:11, color:'var(--success)', marginTop:4 }}>✓ Passwords match</div>}
            </div>
            <button className="btn btn-primary btn-lg" style={{ width:'100%' }} onClick={handleResetPassword}
              disabled={loading || !newStr.strong || form.new_password !== form.confirm}>
              {loading ? <><div className="spinner"/>Saving...</> : '🔒 Reset Password'}
            </button>
          </>)}

          <div style={{ textAlign:'center', fontSize:12, color:'var(--text3)', marginTop:16 }}>
            Remember it? <span style={{ color:'var(--accent)', cursor:'pointer', fontWeight:600 }} onClick={() => switchTab('login')}>Login here</span>
          </div>
        </>)}
      </div>
    </div>
  );
};

export default AuthPage;
